// Server-side internationalization.
//
// Provides a single message catalog (en / hi / ta, plus te for notification
// templates) and two helpers:
//
//   t(lang, key, params)   -> localized string for a catalog key
//   tReq(req, key, params) -> localized string using the request language
//
// The request language is resolved from, in priority order:
//   1. The `Accept-Language` header sent by the frontend (current UI language)
//   2. The logged-in user's `preferredLanguage` (saved on their profile)
//   3. English (fallback)
//
// Keeping the catalog server-side means every API response message, PDF label,
// email line and notification is translated at the point it is produced — the
// Angular frontend just displays whatever string it receives.

const SUPPORTED_LANGUAGES = ["en", "hi", "ta", "te", "kn", "ml"];

