  "pdf.arrival": "ಆಗಮನ",
  "pdf.terms": "ನಿಯಮಗಳು ಮತ್ತು ಷರತ್ತುಗಳು: ಈ ಟಿಕೆಟ್ ಮೇಲೆ ತೋರಿಸಿದ ಪ್ರಯಾಣಕ್ಕೆ ಮಾತ್ರ ಮಾನ್ಯ. ಪ್ರಯಾಣಿಸುವಾಗ ಮಾನ್ಯ ಗುರುತಿನ ಪುರಾವೆಯನ್ನು ಹೊಂದಿರಿ. ಮರುನಿಗದಿಪಡಿಸುವಿಕೆ ಮತ್ತು ರದ್ದುಮಾಡುವಿಕೆಯು ಸಂಚಾರಿಯ ನೀತಿಯಿಂದ ನಿಯಂತ್ರಿಸಲ್ಪಡುತ್ತದೆ. TEDBUS ಒಂದು ಬುಕಿಂಗ್ ಸೌಲಭ್ಯದಾರ; ಪ್ರಯಾಣಕ್ಕೆ ಬಸ್ ಸಂಚಾರಿ ಜವಾಬ್ದಾರ. ದಯವಿಟ್ಟು ಹೊರಡುವುದಕ್ಕೆ 15 ನಿಮಿಷಗಳ ಮುಂಚಿತವಾಗಿ ಏರಿದ ಸ್ಥಳದಲ್ಲಿ ಇರಿ.",
