/** Resolves the language to use for a given request. */
function resolveLang(req) {
  if (!req || !req.headers) return "en";
  const header = String(req.headers["accept-language"] || "")
    .split(",")[0]
    .trim()
    .toLowerCase()
    .slice(0, 2);
  if (SUPPORTED_LANGUAGES.includes(header)) return header;
  const pref = req.user && req.user.preferredLanguage;
  if (pref && SUPPORTED_LANGUAGES.includes(String(pref))) return String(pref);
  return "en";
}

/**
 * Returns a localized string for `key`, interpolating `{{param}}` placeholders.
 * Falls back to English, then to the raw key, when a translation is missing.
 */
function t(lang, key, params) {
  const l = SUPPORTED_LANGUAGES.includes(String(lang)) ? String(lang) : "en";
  let tmpl =
    (CATALOG[l] && CATALOG[l][key]) ||
    CATALOG.en[key] ||
    key;
  if (params) {
    for (const name of Object.keys(params)) {
      tmpl = tmpl.split(`{{${name}}}`).join(String(params[name] ?? ""));
    }
  }
  return tmpl;
}

/** Localized string resolved from a request's language. */
function tReq(req, key, params) {
  return t(resolveLang(req), key, params);
}

module.exports = {
  t,
  tReq,
  resolveLang,
  CATALOG,
  SUPPORTED_LANGUAGES,
};
